dtsPropsFor.AppShell:
/** Signed-in user; role "admin" unlocks the Basic/Advanced view switch. */
  session: { id: string; name: string; email: string; title: string; team: string; status: string; avatar: string; role: "admin" | "user"; accessToken?: string; sessionType: "demo" | "oidc" };
  children: React.ReactNode;

dtsPropsFor.ActionOutcome:
outcome: { kind: "applied" | "queued" | "no_change" | "refused" | "failed"; /** What happened, in physical terms. */ message: string; detail?: string; /** Present on refused and failed. */ requestId?: string };
  placement?: "inline" | "block";
  className?: string;

dtsPropsFor.PlanReview:
plan: { op: "assign_role" | "remove_role" | "assign_bundle" | "remove_bundle" | "extend" | "create_mapping" | "edit_mapping" | "delete_mapping" | "rollback_mappings" | "publish_bundle_version" | "move_bundle_holders"; /** Present on a rehearsal (the approval an apply must cite). */ plan_id?: string; applied: boolean; outcomes: Array<{ user_id: string; name: string; email: string; effect: "apply" | "applied" | "no_change" | "blocked" | "failed" | "queued"; detail: string; consequence?: string; grant_ids?: string[] }>; summary: { total: number; apply: number; no_change: number; blocked: number; failed: number; succeeded: number; queued: number } };
  /** What the plan rows are, singular/plural, e.g. ["account", "accounts"]. */
  noun?: [string, string];

dtsPropsFor.ReadFreshness:
state: { /** When the target was read; absent = never. */ readAt?: string | null; /** false = from the add-on mirror (provisional at any age). */ current?: boolean; /** The read hit the add-on cap. */ truncated?: boolean };
  subject?: string;
  onRefresh?: () => void;
  refreshing?: boolean;
  className?: string;

dtsPropsFor.Withheld:
items: Array<{ /** Entitlement field it applies to, e.g. "group", "share". */ field: string; /** The value withheld, as the member would recognise it. */ value: string; reason: string; /** Which system it is on. */ target?: string; /** Who decided it. */ actorId?: string; /** Past the promised review date. */ reviewDue?: boolean }>;
  audience?: "member" | "operator";
  className?: string;

dtsPropsFor.Segmented:
/** Generic over the option value type in source; string here. */
  options: { value: string; label: string; }[];
  value: string;
  onChange: (next: string) => void;
  size?: "sm" | "md";
  label: string;

dtsPropsFor.FilterPills:
/** Generic over the option value type in source; string here. */
  options: { value: string; label: string; }[];
  value: string;
  onChange: (next: string) => void;
  label: string;

dtsPropsFor.Tabs:
/** Generic over the option value type in source; string here. */
  options: { value: string; label: React.ReactNode; }[];
  value: string;
  onSelect: (next: string) => void;
  /** Names the group for a screen reader — "Views of this person's access". */
  label: string;
  className?: string;

dtsPropsFor.SortHead:
label: string;
  /** Generic over the sort key type in source; string here. */
  name: string;
  /** From `useSort`: the heading in force and its direction. */
  sort: { key: string; dir: 1 | -1 };
  onSort: (key: string) => void;
  /** What a screen reader hears after "Sort by"; the label, lower-cased, by default. */
  by?: string;

dtsPropsFor.ReadLine:
/** Generic over NavSection in source; NavSection here. */
  sections: Array<{ /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }>;
  onOpen?: (section: { /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }) => void;
  /** Names the chips for a screen reader: "Sections of drift". */
  label: string;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.SectionPill:
/** Generic over NavSection in source; NavSection here. */
  sections: Array<{ /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }>;
  onOpen?: (section: { /** The id of the heading's element; the page scrolls to it. */ id: string; /** The short name on the chip. */ label: string; count: number; /** A dot before the name; none when omitted. */ tone?: "neutral" | "accent" | "warn" | "danger" | "healthy" }) => void;
  label: string;
  gap?: number;

dtsPropsFor.PushedStep:
/** The return of `useCancelStep({ host, goAhead, tone?, standalone? })`; `step.run(write)` pushes the step when the write is refused with WouldCancelQueued. */
  step: { run: <T>(write: () => Promise<T>) => Promise<T | symbol>; open: boolean; note: React.ReactNode; after: React.ReactNode; element: React.ReactNode; view: React.ReactNode };
  children: React.ReactNode;

dtsPropsFor.GlideIndicator:
/** From `useGlideIndicator(choice)`: the active button's box, null until measured. */
  box: { left: number; top: number; width: number; height: number } | null;
  kind: "fill" | "underline";
  /** The indicator's colour, a token class. */
  className?: string;
